<?php
$args=[];$where='';if($user['role']==='employee'){$where=' WHERE a.employee_id=?';$args[]=$user['id'];}
$rows=query_rows('SELECT a.*,u.full_name,u.employee_code FROM attendance a JOIN users u ON u.id=a.employee_id'.$where.' ORDER BY attendance_date DESC,a.id DESC',$args);
?><section class="card"><h2>Attendance Records</h2><div class="table-container"><table class="table"><thead><tr><th>Employee</th><th>Date</th><th>Status</th><th>Check-in</th><th>Check-out</th><?php if($user['role']==='admin'):?><th>Actions</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['employee_code'].' — '.$r['full_name'])?></td><td><?=h($r['attendance_date'])?></td><td><?=h($r['status'])?></td><td><?=h($r['check_in']??'—')?></td><td><?=h($r['check_out']??'—')?></td><?php if($user['role']==='admin'):?><td><div class="actions"><a class="btn btn-primary" href="?edit=<?=$r['id']?>">Edit</a><?php delete_form((int)$r['id']);?></div></td><?php endif;?></tr><?php endforeach;if(!$rows)echo '<tr><td colspan="6">No attendance records yet.</td></tr>';?></tbody></table></div></section>
